package com.hotelmanagement.hms.purchase.model; import jakarta.persistence.*; import java.math.*; import java.util.*;
@Entity @Table(name="purchase_order_items") public class PurchaseOrderItem { @Id UUID id=UUID.randomUUID(); @Column(name="hotel_id") UUID hotelId; @Column(name="branch_id") UUID branchId; @Column(name="purchase_order_id") UUID purchaseOrderId; @Column(name="product_id") UUID productId; BigDecimal quantity,unitPrice,receivedQuantity; protected PurchaseOrderItem(){} public static PurchaseOrderItem create(UUID h,UUID b,UUID o,UUID p,BigDecimal q,BigDecimal price){var i=new PurchaseOrderItem();i.hotelId=h;i.branchId=b;i.purchaseOrderId=o;i.productId=p;i.quantity=q;i.unitPrice=price;i.receivedQuantity=BigDecimal.ZERO;return i;} public UUID getProductId(){return productId;} public BigDecimal getQuantity(){return quantity;} public BigDecimal getReceivedQuantity(){return receivedQuantity;} public void receive(BigDecimal q){if(receivedQuantity.add(q).compareTo(quantity)>0)throw new IllegalArgumentException("Received quantity exceeds ordered quantity.");receivedQuantity=receivedQuantity.add(q);} }
